7	pub fn with_handler<T>(
8	    run: impl FnOnce(&Handler) -> Result<T, ErrorEmitted>,
9	) -> Result<T, ParseFileError> {
10	    let handler = <_>::default();
11	    let res = run(&handler);
12	    let (errors, _warnings, _infos) = handler.consume();
13	    res.ok()
14	        .filter(|_| errors.is_empty())
15	        .ok_or(ParseFileError(errors))
16	}
